import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { CustomPaginationComponent } from '../../../shared/service/custom-pagination/custom-pagination.component';
import { QuizResultsService, QuizResult, QuizResultsResponse } from '../../../shared/service/quiz/quiz-results.service';

@Component({
  selector: 'app-superadmin-quiz-results',
  imports: [CommonModule, FormsModule, CustomPaginationComponent],
  templateUrl: './superadmin-quiz-results.component.html',
  styleUrl: './superadmin-quiz-results.component.scss'
})
export class SuperadminQuizResultsComponent implements OnInit {
  results: QuizResult[] = [];
  filteredResults: QuizResult[] = [];
  totalResults = 0;
  loading = false;

  filterQuizId: number | null = null;
  filterUserId: number | null = null;
  filterStatus: string = 'all';

  currentPage = 1;
  pageSize = 10;
  totalData = 0;

  constructor(private quizResultsService: QuizResultsService) {}

  ngOnInit(): void {
    this.loadResults();
  }

  loadResults(): void {
    this.loading = true;
    this.quizResultsService.getAllResults().subscribe({
      next: (response: QuizResultsResponse) => {
        this.results = response.results;
        this.filteredResults = [...this.results];
        this.totalResults = response.total_in_db;
        this.applyFilters();
        this.loading = false;
      },
      error: () => { this.loading = false; }
    });
  }

  applyFilters(): void {
    this.filteredResults = this.results.filter(result => {
      let matches = true;
      if (this.filterQuizId !== null) matches = matches && result.quiz_id === this.filterQuizId;
      if (this.filterUserId !== null) matches = matches && result.user_id === this.filterUserId;
      if (this.filterStatus !== 'all') matches = matches && (this.filterStatus === 'success' ? result.est_reussi : !result.est_reussi);
      return matches;
    });
    this.totalData = Math.ceil(this.filteredResults.length / this.pageSize);
    this.currentPage = 1;
  }

  clearFilters(): void {
    this.filterQuizId = null;
    this.filterUserId = null;
    this.filterStatus = 'all';
    this.applyFilters();
  }

  getPaginatedResults(): QuizResult[] {
    const startIndex = (this.currentPage - 1) * this.pageSize;
    return this.filteredResults.slice(startIndex, startIndex + this.pageSize);
  }

  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalData) this.currentPage = page;
  }

  parseFloat(value: string): number { return parseFloat(value); }

  getSuccessRate(): number {
    if (!this.filteredResults.length) return 0;
    return Math.round(this.filteredResults.filter(r => r.est_reussi).length / this.filteredResults.length * 100);
  }

  getAverageScore(): number {
    if (!this.filteredResults.length) return 0;
    const total = this.filteredResults.reduce((sum, r) => sum + parseFloat(r.note), 0);
    return Math.round(total / this.filteredResults.length * 100) / 100;
  }

  formatDate(dateString: string): string {
    return new Date(dateString).toLocaleDateString('fr-FR', {
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit'
    });
  }

  sortData(event: any): void {}
}
